// --- acr_nav.FCtype.c_field.Insert
// Insert pointer to row into array. Row must not already be in array.
// If pointer is already in the array, it may be inserted twice.
void acr_nav::c_field_Insert(acr_nav::FCtype& ctype, acr_nav::FField& row) {
    if (!row.ctype_c_field_in_ary) {
        c_field_Reserve(ctype, 1);
        u32 n  = ctype.c_field_n++;
        ctype.c_field_elems[n] = &row;
        row.ctype_c_field_in_ary = true;
    }
}

// --- acr_nav.FCtype.c_field.InsertMaybe
// Insert pointer to row in array.
// If row is already in the array, do nothing.
// Return value: whether element was inserted into array.
bool acr_nav::c_field_InsertMaybe(acr_nav::FCtype& ctype, acr_nav::FField& row) {
    bool retval = !ctype_c_field_InAryQ(row);
    c_field_Insert(ctype,row); // check is performed in _Insert again
    return retval;
}

// --- acr_nav.FCtype.c_field.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void acr_nav::c_field_Remove(acr_nav::FCtype& ctype, acr_nav::FField& row) {
    int n = ctype.c_field_n;
    if (bool_Update(row.ctype_c_field_in_ary,false)) {
        acr_nav::FField* *elems = ctype.c_field_elems;
        // search backward, so that most recently added element is found first.
        // if found, shift array.
        for (int i = n-1; i>=0; i--) {
            acr_nav::FField* elem = elems[i]; // fetch element
            if (elem == &row) {
                int j = i + 1;
                size_t nbytes = sizeof(acr_nav::FField*) * (n - j);
                memmove(elems + i, elems + j, nbytes);
                ctype.c_field_n = n - 1;
                break;
            }
        }
    }
}

// --- acr_nav.FCtype.c_field.Reserve
// Reserve space in index for N more elements;
void acr_nav::c_field_Reserve(acr_nav::FCtype& ctype, u32 n) {
    u32 old_max = ctype.c_field_max;
    if (UNLIKELY(ctype.c_field_n + n > old_max)) {
        u32 new_max  = u32_Max(4, old_max * 2);
        u32 old_size = old_max * sizeof(acr_nav::FField*);
        u32 new_size = new_max * sizeof(acr_nav::FField*);
        void *new_mem = algo_lib::malloc_ReallocMem(ctype.c_field_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("acr_nav.out_of_memory  field:acr_nav.FCtype.c_field");
        }
        ctype.c_field_elems = (acr_nav::FField**)new_mem;
        ctype.c_field_max = new_max;
    }
}

