// --- acr_nav.FDb.field.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_nav::field_XrefMaybe(acr_nav::FField &row) {
    bool retval = true;
    (void)row;
    acr_nav::FCtype* p_ctype = acr_nav::ind_ctype_Find(ctype_Get(row));
    if (UNLIKELY(!p_ctype)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_ctype" << Keyval("key", ctype_Get(row));
        return false;
    }
    // field: save pointer to ctype
    if (true) { // user-defined insert condition
        row.p_ctype = p_ctype;
    }
    acr_nav::FCtype* p_arg = acr_nav::ind_ctype_Find(row.arg);
    if (UNLIKELY(!p_arg)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_ctype" << Keyval("key", row.arg);
        return false;
    }
    // field: save pointer to arg
    if (true) { // user-defined insert condition
        row.p_arg = p_arg;
    }
    acr_nav::FReftype* p_reftype = acr_nav::ind_reftype_Find(row.reftype);
    if (UNLIKELY(!p_reftype)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_reftype" << Keyval("key", row.reftype);
        return false;
    }
    // field: save pointer to reftype
    if (true) { // user-defined insert condition
        row.p_reftype = p_reftype;
    }
    // insert field into index ind_field
    if (true) { // user-defined insert condition
        bool success = ind_field_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_nav.duplicate_key  xref:acr_nav.FDb.ind_field"; // check for duplicate key
            return false;
        }
    }
    // insert field into index c_field
    if (true) { // user-defined insert condition
        c_field_Insert(*p_ctype, row);
    }
    return retval;
}

