// Find row by key. If not found, create and x-reference a new row with with this key.
acr_nav::FNs& acr_nav::ind_ns_GetOrCreate(const algo::strptr& key) {
    acr_nav::FNs* ret = ind_ns_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &ns_Alloc();
        (*ret).ns = key;
        bool good = ns_XrefMaybe(*ret);
        if (!good) {
            ns_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "acr_nav.create_error  table:ind_ns  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- acr_nav.FDb.ind_ns.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool acr_nav::ind_ns_InsertMaybe(acr_nav::FNs& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_ns_next == (acr_nav::FNs*)-1)) {// check if in hash already
        row.ind_ns_hashval = algo::Smallstr16_Hash(0, row.ns);
        ind_ns_Reserve(1);
        u32 index = row.ind_ns_hashval & (_db.ind_ns_buckets_n - 1);
        acr_nav::FNs* *prev = &_db.ind_ns_buckets_elems[index];
        do {
            acr_nav::FNs* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).ns == row.ns) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_ns_next;
        } while (true);
        if (retval) {
            row.ind_ns_next = *prev;
            _db.ind_ns_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- acr_nav.FDb.ind_ns.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void acr_nav::ind_ns_Remove(acr_nav::FNs& row) {
    if (LIKELY(row.ind_ns_next != (acr_nav::FNs*)-1)) {// check if in hash already
        u32 index = row.ind_ns_hashval & (_db.ind_ns_buckets_n - 1);
        acr_nav::FNs* *prev = &_db.ind_ns_buckets_elems[index]; // addr of pointer to current element
        while (acr_nav::FNs *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_ns_next; // unlink (singly linked list)
                _db.ind_ns_n--;
                row.ind_ns_next = (acr_nav::FNs*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_ns_next;
        }
    }
}

// --- acr_nav.FDb.ind_ns.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void acr_nav::ind_ns_Reserve(int n) {
    ind_ns_AbsReserve(_db.ind_ns_n + n);
}

// --- acr_nav.FDb.ind_ns.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void acr_nav::ind_ns_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_ns_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(acr_nav::FNs*);
        u32 new_size = new_nbuckets * sizeof(acr_nav::FNs*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        acr_nav::FNs* *new_buckets = (acr_nav::FNs**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("acr_nav.out_of_memory  field:acr_nav.FDb.ind_ns");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_ns_buckets_n; i++) {
            acr_nav::FNs* elem = _db.ind_ns_buckets_elems[i];
            while (elem) {
                acr_nav::FNs &row        = *elem;
                acr_nav::FNs* next       = row.ind_ns_next;
                u32 index          = row.ind_ns_hashval & (new_nbuckets-1);
                row.ind_ns_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_ns_buckets_elems, old_size);
        _db.ind_ns_buckets_elems = new_buckets;
        _db.ind_ns_buckets_n = new_nbuckets;
    }
}

