// --- acr_nav.FDb.keybind.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool acr_nav::keybind_XrefMaybe(acr_nav::FKeybind &row) {
    bool retval = true;
    (void)row;
    acr_nav::FNavaction* p_navaction = acr_nav::ind_navaction_Find(row.navaction);
    if (UNLIKELY(!p_navaction)) {
        algo_lib::ResetErrtext() << "acr_nav.bad_xref  index:acr_nav.FDb.ind_navaction" << Keyval("key", row.navaction);
        return false;
    }
    // keybind: save pointer to navaction
    if (true) { // user-defined insert condition
        row.p_navaction = p_navaction;
    }
    // insert keybind into index ind_keybind
    if (true) { // user-defined insert condition
        bool success = ind_keybind_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "acr_nav.duplicate_key  xref:acr_nav.FDb.ind_keybind"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

