// --- acr_nav.TableId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* acr_nav::value_ToCstr(const acr_nav::TableId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case acr_nav_TableId_dmmeta_Ctype  : ret = "dmmeta.Ctype";  break;
        case acr_nav_TableId_dmmeta_Field  : ret = "dmmeta.Field";  break;
        case acr_nav_TableId_acr_navdb_Keybind: ret = "acr_navdb.Keybind";  break;
        case acr_nav_TableId_acr_navdb_Navmode: ret = "acr_navdb.Navmode";  break;
        case acr_nav_TableId_dmmeta_Ns     : ret = "dmmeta.Ns";  break;
        case acr_nav_TableId_acr_navdb_Panel: ret = "acr_navdb.Panel";  break;
        case acr_nav_TableId_dmmeta_Reftype: ret = "dmmeta.Reftype";  break;
    }
    return ret;
}

// --- acr_nav.TableId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void acr_nav::value_Print(const acr_nav::TableId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

// --- acr_nav.TableId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool acr_nav::value_SetStrptrMaybe(acr_nav::TableId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 9: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','m','m','e','t','a','.','N'): {
                    if (memcmp(rhs.elems+8,"s",1)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_Ns); ret = true; break; }
                    break;
                }
                case LE_STR8('d','m','m','e','t','a','.','n'): {
                    if (memcmp(rhs.elems+8,"s",1)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_ns); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 12: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','m','m','e','t','a','.','C'): {
                    if (memcmp(rhs.elems+8,"type",4)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_Ctype); ret = true; break; }
                    break;
                }
                case LE_STR8('d','m','m','e','t','a','.','F'): {
                    if (memcmp(rhs.elems+8,"ield",4)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_Field); ret = true; break; }
                    break;
                }
                case LE_STR8('d','m','m','e','t','a','.','c'): {
                    if (memcmp(rhs.elems+8,"type",4)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_ctype); ret = true; break; }
                    break;
                }
                case LE_STR8('d','m','m','e','t','a','.','f'): {
                    if (memcmp(rhs.elems+8,"ield",4)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_field); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 14: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','m','m','e','t','a','.','R'): {
                    if (memcmp(rhs.elems+8,"eftype",6)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_Reftype); ret = true; break; }
                    break;
                }
                case LE_STR8('d','m','m','e','t','a','.','r'): {
                    if (memcmp(rhs.elems+8,"eftype",6)==0) { value_SetEnum(parent,acr_nav_TableId_dmmeta_reftype); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 15: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','c','r','_','n','a','v','d'): {
                    if (memcmp(rhs.elems+8,"b.Panel",7)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_Panel); ret = true; break; }
                    if (memcmp(rhs.elems+8,"b.panel",7)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_panel); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 17: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('a','c','r','_','n','a','v','d'): {
                    if (memcmp(rhs.elems+8,"b.Keybind",9)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_Keybind); ret = true; break; }
                    if (memcmp(rhs.elems+8,"b.keybind",9)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_keybind); ret = true; break; }
                    if (memcmp(rhs.elems+8,"b.Navmode",9)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_Navmode); ret = true; break; }
                    if (memcmp(rhs.elems+8,"b.navmode",9)==0) { value_SetEnum(parent,acr_nav_TableId_acr_navdb_navmode); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

// --- acr_nav.TableId.value.SetStrptr
// Convert string to field.
// If the string is invalid, set numeric value to DFLT
void acr_nav::value_SetStrptr(acr_nav::TableId& parent, algo::strptr rhs, acr_nav_TableIdEnum dflt) {
    if (!value_SetStrptrMaybe(parent,rhs)) value_SetEnum(parent,dflt);
}

// --- acr_nav.TableId.value.ReadStrptrMaybe
// Convert string to field. Return success value
bool acr_nav::value_ReadStrptrMaybe(acr_nav::TableId& parent, algo::strptr rhs) {
    bool retval = false;
    retval = value_SetStrptrMaybe(parent,rhs); // try symbol conversion
    if (!retval) { // didn't work? try reading as underlying type
        retval = i32_ReadStrptrMaybe(parent.value,rhs);
    }
    return retval;
}

